'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),rp=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0);const L=window.THLaundryLabel,UI=window.THLaundryUI;let assignees=[],rooms=[],orders=[],member,selected=new URLSearchParams(location.search).get('order')||null,detail,tab='orders',pageCursor='',nextCursor,stream,busy=false;let loading=false,lastRooms=0,uploading=false,capturing=false,orderLoad=0;let filter={start:'',end:'',search:'',status:''};
const field=(name,label,type='text',value='',required=true)=>`<label>${label}${required?' <span class="field-requirement">Wajib</span>':''}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
const choice=(name,label,items,value='')=>`<label>${label}<select name="${name}">${items.map(v=>{const [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`;
function msg(text,error=false){$('#message').className='alert '+(error?'error':'success');$('#message').textContent=THCopy.error(text);}
async function api(path,data){const r=await fetch('/api/laundry/'+path,{method:data?'POST':'GET',credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(20000),headers:data instanceof FormData?{'X-Top-Hills':'1'}:{'Content-Type':'application/json','X-Top-Hills':'1'},body:data instanceof FormData?data:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok){if(r.status===401){$('#view').innerHTML='<h1>Masuk sebagai petugas.</h1><p>Masuk menggunakan akun tim Anda. Owner memberikan peran Operator/Finance setelah akun terdaftar di dashboard utama.</p><a class="button primary" href="/login">Masuk ke Top Hills</a>'; }throw Error(v.error||'Penyimpanan gagal.');}return v;}
function dialog(title,body,submit){
 const modal=$('#modal');modal.innerHTML=`<h2>${esc(title)}</h2><form id="modal-form" class="grid">${body}<p id="modal-message" class="alert danger full" role="alert" hidden></p><div class="full row dialog-footer"><button class="primary" type="submit">Simpan</button><button type="button" id="close">Batal</button></div></form>`;
 modal.showModal();$('#close').onclick=()=>modal.close();const form=$('#modal-form');UI.bindPicker(form);UI.bindWeigh(form);$('#modal [data-action-camera]')?.addEventListener('click',()=>camera('#action-camera-box'));$('#modal [data-action-upload]')?.addEventListener('change',e=>upload(e.target.files[0],'upload'));
 form.onsubmit=async e=>{e.preventDefault();if(busy||uploading||capturing)return;const btn=e.submitter;btn.disabled=true;busy=true;const out=$('#modal-message');out.hidden=true;
 try{await submit(UI.serialize(form));modal.close();}catch(error){out.textContent=error.message;out.hidden=false;out.scrollIntoView({block:'nearest'});}finally{btn.disabled=false;busy=false;}};
}

async function load(force=true){if(loading)return;loading=true;try{if(!member||Date.now()-lastRooms>60000){const r=await api('rooms');rooms=r.rooms;member=r.member;assignees=r.assignees||[];lastRooms=Date.now();if(!rooms.length&&member.role==='Owner'){await api('rooms/init',{});rooms=(await api('rooms')).rooms;}}if(selected){await openOrder(selected);return;}const query=new URLSearchParams({...filter,cursor:pageCursor});const v=await api('orders?'+query);const unchanged=JSON.stringify(orders)===JSON.stringify(v.orders)&&nextCursor===v.nextCursor;orders=v.orders;nextCursor=v.nextCursor;if(force||tab==='rooms'||!unchanged||!$('#tab-orders'))render();}catch(e){msg(e.name==='TimeoutError'?'Koneksi lambat. Data belum diperbarui.':e.message,true);}finally{loading=false;}}

function render(){
 if(selected)return openOrder(selected);
 const shown=orders.filter(o=>(!filter.search||JSON.stringify([o.id,o.customer.name,o.room.id]).toLowerCase().includes(filter.search.toLowerCase()))&&(!filter.status||o.status===filter.status)).sort((a,b)=>Number(THLaundryFocus.terminal(a))-Number(THLaundryFocus.terminal(b))||THLaundryFocus.openIssues(b).length-THLaundryFocus.openIssues(a).length);
 $('#view').innerHTML=`<div class="row spread desk-heading"><div><h1>Meja laundry</h1><p class="muted">Pilih pesanan, lalu ikuti satu langkah yang ditampilkan.</p></div>${member.role!=='Finance'?'<button class="primary" id="assisted">+ Terima pesanan</button>':''}</div><nav class="desk-tools" aria-label="Pilihan meja laundry"><button id="tab-orders" aria-pressed="${tab==='orders'}">Antrean</button>${member.role==='Owner'?`<button id="tab-rooms" aria-pressed="${tab==='rooms'}">Kamar & QR</button>`:''}<button id="guide-library">Panduan kerja</button><button id="closing">Akhir shift</button><button id="reload" aria-label="Perbarui daftar pesanan">Perbarui</button></nav>${tab==='rooms'?roomTable():`<form id="filters" class="queue-filters"><label>Cari pesanan<input name="search" type="search" value="${esc(filter.search)}" placeholder="Nomor pesanan, nama, atau kamar"></label><details><summary>Saring tanggal dan status</summary><div class="grid">${field('start','Dari tanggal','date',filter.start,false)}${field('end','Sampai tanggal','date',filter.end,false)}${choice('status','Status',[['','Semua status'],...['SUBMITTED','AWAITING PICKUP','AWAITING DROPOFF','PICKED UP','RECEIVED AT COUNTER','QUARANTINE','PRICE CONFIRMATION PENDING','IN PROCESS','READY FOR HANDOVER','COMPLETED','CANCELLED','LINKED','ON HOLD'].map(x=>[x,L(x)])],filter.status)}</div></details><button type="submit">Cari</button></form><p class="queue-count">${shown.length} catatan di halaman ini</p><div class="order-queue">${shown.map(o=>{const f=THLaundryFocus.focus(o,member.role,available(o));return `<article class="order-card"><div class="order-card-heading"><div><h2>${esc(o.customer.name||'Pemilik belum diketahui')}</h2><small>${esc(o.id)}${o.room.id!=='UNKNOWN'?' · Kamar '+esc(o.room.id):''}</small></div>${UI.badge(f.complete?'CLEAR':o.status,o.status==='LINKED'?'Sudah menjadi pesanan':L(o.status))}</div><p class="queue-next ${f.tone}">${UI.icon(f.tone)}<span>${esc(f.title)}${f.waitingFor?' · '+esc(f.waitingFor):''}</span></p><div class="row spread"><small>${o.kind==='THL'&&o.price?rp(o.price.total)+' · '+esc(L(o.pay.status)):o.kind==='INT'?'Catatan penerimaan barang':'Belum ada tagihan'}</small><button data-open="${esc(o.id)}">Buka ${o.kind==='INT'?'catatan':'pesanan'}</button></div></article>`}).join('')||'<div class="empty">Belum ada pesanan yang cocok.</div>'}</div><div class="row queue-pages">${nextCursor?'<button id="next">Halaman berikutnya</button>':''}${pageCursor?'<button id="first">Halaman pertama</button>':''}</div>`}`;
 $('#guide-library').onclick=()=>THLaundryGuideUI.library();$('#closing').onclick=closing;$('#reload').onclick=load;$('#tab-orders').onclick=()=>{tab='orders';render()};$('#tab-rooms')?.addEventListener('click',()=>{tab='rooms';render()});$('#assisted')?.addEventListener('click',assisted);$('#filters')?.addEventListener('submit',e=>{e.preventDefault();filter={...filter,...Object.fromEntries(new FormData(e.target))};pageCursor='';load()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.open;openOrder(selected)});document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>editRoom(b.dataset.room));$('#next')?.addEventListener('click',()=>{pageCursor=nextCursor;load()});$('#first')?.addEventListener('click',()=>{pageCursor='';load()});
}
function roomTable(){return `<div class="alert">117 kamar dari SOP. Isi lantai dan jenis kamar sesuai kondisi nyata sebelum mengaktifkan QR. Kode QR tidak ditampilkan dalam daftar publik. Mengganti QR membuat QR lama tidak berlaku.</div><div class="table-wrap"><table><thead><tr><th>KAMAR</th><th>LANTAI / JENIS</th><th>CHECKOUT</th><th>STATUS</th><th></th></tr></thead><tbody>${rooms.map(r=>`<tr><td><strong>${esc(r.id)}</strong>Gedung ${esc(r.building)}</td><td>${esc(r.floor||'Belum diisi')} · ${esc(r.roomType||r.type)}</td><td>${r.checkout?esc(new Date(r.checkout).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})):'—'}</td><td>${r.active?'Aktif':'Nonaktif'} · QR ${r.hasQR?'tersedia':'belum dibuat'}</td><td><button data-room="${esc(r.id)}">Atur kamar</button></td></tr>`).join('')}</tbody></table></div>`;}
function showLink(path,title,qr=false){$('#modal').innerHTML=`<h2>${esc(title)}</h2><p>Tautan ini bersifat pribadi. ${qr?'Tempel QR hanya pada kamar yang sesuai.':'Berikan hanya kepada pemilik order.'}</p>${qr?'<canvas id="qr" class="qr"></canvas>':''}<div class="row"><a class="button primary" target="_blank" rel="noreferrer" href="${esc(path)}">Buka halaman</a><button id="copy-link">Salin tautan</button>${qr?'<button id="download-qr">Unduh QR</button>':''}<button id="dismiss">Tutup</button></div>`;$('#modal').showModal();const full=location.origin+path;if(qr){makeRoomQR($('#qr'),full);$('#download-qr').onclick=()=>{const a=document.createElement('a');a.href=$('#qr').toDataURL();a.download='Top-Hills-QR.png';a.click()};}$('#copy-link').onclick=()=>navigator.clipboard.writeText(full).then(()=>msg('Tautan disalin.'));$('#dismiss').onclick=()=>$('#modal').close();}
function editRoom(id){const r=rooms.find(x=>x.id===id);dialog('Kamar '+id,field('floor','Lantai','text',r.floor)+field('roomType','Jenis kamar','text',r.roomType)+field('checkout','Checkout (penginapan)','datetime-local',r.checkout?new Date(Date.parse(r.checkout)+7*3600000).toISOString().slice(0,16):'',false)+`<label class="check"><input type="checkbox" name="active" ${r.active?'checked':''}>Kamar aktif</label><label class="check full"><input type="checkbox" name="rotate">Buat / ganti QR kamar</label>`,async p=>{const v=await api('room',{...p,id,revision:r.revision,active:p.active==='on',rotate:p.rotate==='on',checkout:p.checkout?p.checkout+':00+07:00':''});lastRooms=0;await load();if(v.qrPath)setTimeout(()=>showLink(v.qrPath,'QR kamar '+id,true),30)});}
function assisted(){dialog('Tambah pesanan dibantu petugas',choice('roomId','Kamar',[['UNKNOWN','Pemilik / kamar belum diketahui'],...rooms.filter(r=>r.active).map(r=>[r.id,r.id+' · lantai '+r.floor])])+field('name','Nama (boleh belum diketahui)','text','',false)+field('contact','WhatsApp (boleh belum diketahui)','tel','',false)+choice('relationship','Hubungan',['Penghuni','Tamu','Keluarga'])+choice('method','Metode',[['dropoff','Antar ke counter'],['pickup','Jemput kamar']])+UI.picker(THServices.catalog(),{})+`<p class="alert full">Setelah dibuat, segera ambil foto langsung, catat kantong, lokasi, dan label. Identitas belum lengkap tidak boleh dibayar atau diproses.</p>`,async p=>{const v=await api('assisted',{...p,mutationId:crypto.randomUUID()});selected=v.order.id;await openOrder(selected);if(member.role==='Owner'&&v.trackingPath)setTimeout(()=>showLink(v.trackingPath,'Konfirmasi pelanggan'),30)});}
const actionLabels={'record-return-proof':'Lengkapi bukti pengembalian','refund-account':'Lengkapi rekening pengembalian dana','review-sop':'Catat pemeriksaan SOP','resume':'Lanjutkan tahap sebelumnya','refund-reconcile':'Cocokkan pengembalian dana','assign':'Tugaskan petugas','incident':'Catat kendala / sengketa','set-process-policy':'Atur pembayaran sebelum proses','accept':'Terima order / revisi','receive':'Terima barang & label','confirm-identity':'Verifikasi identitas (Owner)','weigh':'Isi / koreksi timbangan','approve-price':'Catat persetujuan harga','create-pay':'Siapkan pembayaran','payment-proof':'Ajukan bukti pembayaran','verify-pay':'Verifikasi penerimaan','submit-set':'Ajukan setoran','approve-set':'Periksa setoran','process':'Mulai proses laundry','ready':'Periksa kualitas barang','handover':'Serahkan ke pelanggan','cancel':'Ajukan pembatalan','approve-cancel':'Putuskan pembatalan','return':'Kembalikan barang','refund-approve':'Setujui pengembalian dana','refund-pay':'Catat pengembalian dana','paylater':'Izinkan bayar nanti','label-lost':'Laporkan label hilang','relabel':'Foto label pengganti','hold':'Tahan order','void':'Tandai order tidak berlaku','notify-retry':'Catat tindak lanjut komunikasi','expire-pay':'Tandai pembayaran kedaluwarsa','resolve-exception':'Selesaikan kendala'};
function available(o){let a=[];if(member.role==='Owner'&&THLaundryFocus.needsReturnProof(o))a.push('record-return-proof');if(!['COMPLETED','CANCELLED','VOIDED','LINKED'].includes(o.status)){a.push('assign');if(o.kind==='THL'&&(!o.acceptedBy||o.acceptedRevision<o.customerRevision))a.push('accept');if(!o.custody)a.push('receive');if(o.identity!=='CONFIRMED'&&member.role==='Owner'&&o.kind==='THL')a.push('confirm-identity');if(o.custody&&o.label&&o.kind==='THL'&&o.acceptedRevision===o.customerRevision&&['PICKED UP','RECEIVED AT COUNTER','PRICE CONFIRMATION PENDING'].includes(o.status)&&!o.pay.received)a.push('weigh');if(o.price&&!o.priceApproved&&o.identity==='CONFIRMED'&&o.acceptedRevision===o.customerRevision)a.push('approve-price');if(o.priceApproved&&!['PAID','OVERPAID'].includes(o.pay.status))a.push('create-pay');if(['PENDING','PENDING VERIFICATION','UNDERPAID'].includes(o.pay.status))a.push('payment-proof','verify-pay','expire-pay');if((!o.requirePaidBeforeProcess||o.pay.status==='PAID')&&o.price&&o.identity==='CONFIRMED'&&o.acceptedRevision===o.customerRevision&&o.custody&&o.label&&o.status==='PRICE CONFIRMATION PENDING')a.push('process');if(o.status==='IN PROCESS')a.push('ready');if(o.status==='READY FOR HANDOVER'&&o.priceApproved&&(o.pay.status==='PAID'||o.paylater))a.push('handover');if(o.status==='CANCEL REQUESTED')a.push('approve-cancel');if(o.status==='RETURN REQUESTED')a.push('return');a.push('cancel','hold');if(o.custody)a.push(o.label?'label-lost':'relabel');if(member.role==='Owner')a.push('paylater','void','set-process-policy');}if(['IN TRANSIT','SHORT','OVER'].includes(o.set.status))a.push('submit-set');if(o.set.status==='PENDING VERIFICATION'&&member.role!=='Operator')a.push('approve-set');if(o.ref.status==='REQUESTED'&&member.role==='Owner')a.push('refund-approve');if(['APPROVED','PARTIALLY REFUNDED'].includes(o.ref.status)&&member.role!=='Operator')a.push('refund-pay');if(o.exceptions.some(e=>e.open)&&member.role==='Owner')a.push('resolve-exception');if(o.ref.status==='REFUNDED'&&o.ref.settlementAdjustment?.status==='REQUIRES RECONCILIATION'&&member.role!=='Operator')a.push('refund-reconcile');if(o.status==='ON HOLD')a=a.filter(x=>['assign','cancel','relabel','label-lost','resolve-exception','submit-set','approve-set','refund-approve','refund-pay','refund-reconcile'].includes(x)).concat('resume');if(['CANCEL REQUESTED','RETURN REQUESTED'].includes(o.status))a=a.filter(x=>['assign','approve-cancel','return','refund-approve','refund-pay','refund-reconcile','resolve-exception','submit-set','approve-set'].includes(x));if(o.status==='COMPLETED'&&o.priceApproved&&!['PAID','OVERPAID'].includes(o.pay.status))a.push('create-pay');if(o.status==='COMPLETED'&&['PENDING','PENDING VERIFICATION','UNDERPAID'].includes(o.pay.status))a.push('payment-proof','verify-pay');if(member.role!=='Operator'&&o.ref.payments?.some(x=>!x.cashAccount))a.push('refund-account');a.push('review-sop','notify-retry','incident');if(member.role==='Finance')a=a.filter(x=>['review-sop','refund-account','payment-proof','verify-pay','submit-set','approve-set','refund-pay','refund-reconcile','notify-retry'].includes(x));if(o.pay.method!=='Cash'&&member.role==='Operator')a=a.filter(x=>x!=='verify-pay');if(o.requiresOwner&&member.role!=='Owner')a=a.filter(x=>x!=='approve-cancel');if(member.id===o.set.submittedBy||o.pay.attempts.some(x=>x.receivedBy===member.id))a=a.filter(x=>x!=='approve-set');if(o.ref.payments?.some(x=>x.by===member.id))a=a.filter(x=>x!=='refund-reconcile');if(o.pay.status!=='PENDING')a=a.filter(x=>x!=='expire-pay');return [...new Set(a)];}
async function openOrder(id,quiet=false){
 const request=++orderLoad;try{const loaded=await api('order?id='+encodeURIComponent(id));if(request!==orderLoad||selected!==id||uploading)return;if(quiet&&JSON.stringify(loaded)===JSON.stringify(detail))return;detail=loaded;const o=detail.order;
 $('#view').innerHTML=`<div class="order-page"><button id="back">← Antrean</button><div class="order-heading"><span class="eyebrow">${o.kind==='INT'?'Catatan penerimaan':'Pesanan laundry'}</span><h1>${esc(o.customer.name||'Pemilik belum diketahui')}</h1><p class="order-reference">${esc(o.id)}${o.room.id!=='UNKNOWN'?' · Kamar '+esc(o.room.id):''}</p></div><section class="card work-now" aria-labelledby="work-now-title">${actionPanel(o)}</section><div class="order-info-links" aria-label="Informasi tambahan"><span>Informasi saja · tidak perlu diisi</span><div class="row"><button id="order-details">Rincian & bukti</button><button id="order-history">Riwayat</button>${o.kind==='THL'&&member.role!=='Operator'?'<a class="button" href="/?view=finance&order='+encodeURIComponent(o.id)+'">Lihat laporan</a>':''}</div></div></div>`;
 $('#back').onclick=()=>{orderLoad++;selected=null;history.replaceState(null,'','/laundry-desk');stopCamera();load()};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actionForm(b.dataset.action));document.querySelector('[data-guide-link]')?.addEventListener('click',linkInt);$('#order-details').onclick=()=>showOrderInfo('details');$('#order-history').onclick=()=>showOrderInfo('history');$('#other-actions')?.addEventListener('click',showOtherActions);
 }catch(e){msg(e.message,true)}
}
function infoDialog(title,body){
 const modal=$('#modal');modal.innerHTML=`<div class="row spread"><h2>${esc(title)}</h2><button id="info-close">Tutup</button></div>${body}`;modal.showModal();$('#info-close').onclick=()=>modal.close();
}
function showOrderInfo(mode){
 const o=detail.order;
 if(mode==='history'){infoDialog('Riwayat pesanan',`<ol class="timeline">${detail.events.map(e=>{let data={};try{data=JSON.parse(e.data)}catch{}return `<li><strong>${esc(THLaundryActivity(e.action))}</strong><small>${esc(THCopy.person(data.actorName||e.actor))} · ${new Date(e.at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}</small>${data.reason?esc(THCopy.summary(data.reason)):''}</li>`}).join('')||'<li>Belum ada aktivitas tambahan.</li>'}</ol>`);return;}
 const statuses=[['Barang',o.status],...(!THLaundryFocus.terminal(o)?[['Pemilik barang',o.identity]]:[]),...(o.kind==='THL'&&o.price?[['Pembayaran',o.pay.status]]:[]),...(o.pay.received?[['Setoran',o.set.status]]:[]),...(o.ref.amount?[['Pengembalian dana',o.ref.status]]:[])];
 infoDialog('Rincian & bukti',`<div class="status-grid">${statuses.map(([name,status])=>`<div><small>${name}</small>${UI.badge(status)}</div>`).join('')}</div><p><strong>${esc(o.customer.name||'Pemilik belum diketahui')}</strong><br>${esc(o.customer.contact||'Nomor WhatsApp belum diisi')}<br>${o.room.id==='UNKNOWN'?'Kamar belum diketahui':'Kamar '+esc(o.room.id)}</p>${o.customer.note?'<p><strong>Instruksi pelanggan</strong><br>'+esc(o.customer.note)+'</p>':''}${o.kind==='THL'?UI.priceTable(o.price)+priceHistory(o):''}${o.customerRevision>1?revisionPanel(o):''}<h3>Bukti tersimpan</h3><ul id="proof-list">${detail.proofs.map(p=>`<li><a target="_blank" rel="noreferrer" href="/api/laundry/proof?id=${encodeURIComponent(p.id)}">${p.capture==='live'?'Foto langsung':'Dokumen / foto'} · ${new Date(p.created_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}</a></li>`).join('')||'<li>Belum ada bukti.</li>'}</ul>${member.role==='Owner'&&o.kind==='THL'?'<details><summary>Akses pelanggan · khusus Owner</summary><p>Tautan baru menggantikan tautan sebelumnya. Gunakan untuk pengecekan dan berikan hanya kepada pelanggan yang bersangkutan.</p><button id="tracking">Buat tautan pelanggan baru</button></details>':''}`);
 $('#tracking')?.addEventListener('click',async()=>{try{const v=await api('tracking',{id:o.id});showLink(v.trackingPath,'Tautan pelanggan')}catch(e){msg(e.message,true)}});
}
function showOtherActions(){
 const o=detail.order,f=THLaundryFocus.focus(o,member.role,available(o)),actions=optionalActions(o,f.action);
 infoDialog('Tindakan bila diperlukan',`<p class="muted">Pilih hanya jika sesuai kejadian. Ini bukan daftar yang harus dikerjakan semuanya.</p><div class="actions">${actions.map(a=>`<button data-extra-action="${a}">${esc(actionLabels[a])}</button>`).join('')}</div>`);
 document.querySelectorAll('[data-extra-action]').forEach(b=>b.onclick=()=>{$('#modal').close();actionForm(b.dataset.extraAction)});
}
function optionalActions(o,primary){
 if(o.kind==='INT'&&o.status==='LINKED')return [];
 return available(o).filter(a=>a!==primary&&a!=='record-return-proof'&&(!THLaundryFocus.terminal(o)||!['assign','receive','weigh','relabel','process','ready','handover','cancel','hold','paylater','set-process-policy','accept'].includes(a)));
}

function proofSelect(live=false){const list=detail.proofs.filter(p=>!live||p.capture==='live');return `<div class="full action-proof" data-live-proof="${live}"><p class="muted">${live?'Wajib: foto langsung untuk tahap ini.':'Wajib: pilih bukti yang sesuai dengan tindakan ini.'}</p>${choice('proofId',live?'Foto langsung':'Bukti pesanan',[['','Pilih bukti'],...list.map(p=>[p.id,(p.capture==='live'?'Foto langsung':'Unggahan')+' · '+new Date(p.created_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})])])}<div class="row"><button type="button" data-action-camera>Ambil foto sekarang</button>${live?'':'<label class="button">Unggah bukti<input type="file" data-action-upload accept="image/png,image/jpeg,application/pdf" hidden></label>'}</div><div id="action-camera-box"></div><p data-upload-status role="status" aria-live="polite"></p></div>`;}

function actionForm(action){if(action==='review-sop')return reviewScenario();const o=detail.order;let body='';const proofActions=['record-return-proof','receive','confirm-identity','weigh','approve-price','payment-proof','verify-pay','submit-set','ready','handover','return','refund-pay','refund-account','refund-reconcile','relabel','resolve-exception','incident'];if(proofActions.includes(action))body+=proofSelect(['receive','weigh','ready','relabel'].includes(action));if(['record-return-proof','refund-account','assign','resume','refund-reconcile','cancel','approve-cancel','refund-approve','paylater','label-lost','hold','void','resolve-exception','confirm-identity'].includes(action))body+=field('reason','Alasan');if(action==='assign')body+=choice('assignedTo','Petugas bertugas',assignees.map(m=>[m.id,m.name]),o.assignedTo);if(action==='incident')body+=choice('type','Jenis kendala',['Pickup gagal / customer tidak ada','Antrean / target melewati checkout','Barang hilang / rusak','Rework setelah selesai','Sengketa pembayaran','Salah rekening / deposit tidak dikenal','Perubahan harga setelah dibayar','Refund gagal / perlu rekonsiliasi','Kendala lainnya'])+field('reason','Kronologi dan tindakan berikutnya')+field('due','Tenggat tindak lanjut','datetime-local','',false);if(action==='set-process-policy')body+=choice('required','Wajib lunas sebelum proses?',[['yes','Ya, wajib lunas'],['no','Boleh sebelum pembayaran']]);if(action==='receive')body+=field('bags','Jumlah kantong','number',1)+field('location','Lokasi penyimpanan')+field('arrivedAt','Waktu barang sebenarnya tiba','datetime-local','',false);if(action==='weigh')body+=UI.weighEditor(o);if(action==='confirm-identity')body+=field('name','Nama pelanggan','text',o.customer.name)+field('contact','WhatsApp','tel',o.customer.contact);if(action==='create-pay')body+=choice('method','Metode',['Cash','Transfer']);if(['verify-pay','refund-pay'].includes(action))body+=field('amount','Nominal rupiah','number',action==='verify-pay'?o.price.total-o.pay.received:o.ref.amount-(o.ref.paid||0))+field('reference','Referensi bank / kuitansi');if(action==='refund-account')body+=choice('paymentIndex','Pengembalian yang perlu dilengkapi',(o.ref.payments||[]).map((x,i)=>[i,x]).filter(([i,x])=>!x.cashAccount).map(([i,x])=>[i,'Refund '+(i+1)+' · '+rp(x.amount)]));if(['refund-pay','refund-account'].includes(action))body+=choice('cashAccount','Dana dikembalikan dari',[['','Pilih rekening asal'],['1102','Bank operasional'],['1101K','Kas kecil']]);if(action==='refund-reconcile')body+=field('reference','Referensi bank / kas setelah refund')+field('cashReturned','Cash dari penerimaan belum disetor yang dikembalikan (rupiah)','number',0);if(action==='submit-set')body+=field('actual','Total bersih disetor untuk order ini (kumulatif)','number',o.set.gross)+field('fee','Total biaya setoran (kumulatif)','number',0)+field('account','Rekening tujuan')+field('reference','Referensi mutasi');if(action==='process')body+=field('batch','Mesin atau kelompok cucian')+field('scannedId','Nomor pada label barang')+(o.priceApproved?'<p class="alert success full">Harga sudah disetujui. Label harus sama dengan order ini.</p>':`<div class="alert warning full">Konfirmasi pelanggan belum masuk. Hubungi pelanggan terlebih dahulu. Jika perlu dilanjutkan, catat dasar keputusan di bawah.</div>${choice('overrideContext','Dasar melanjutkan',[['','Pilih dasar keputusan'],['CUSTOMER_BUSY','Pelanggan sibuk / belum membalas'],['VERBAL_INSTRUCTION','Sudah diminta lanjut secara langsung'],['LONG_WAIT','Sudah menunggu terlalu lama']])}<label class="full">Alasan lengkap<textarea name="reason" required minlength="20" maxlength="1000" placeholder="Tuliskan waktu menunggu, upaya menghubungi, dan mengapa pekerjaan perlu dilanjutkan."></textarea></label><label class="check full"><input type="checkbox" name="proceedWithoutApproval" required>Saya bertanggung jawab memulai proses ini. Konfirmasi harga pelanggan tetap ditunggu.</label>`);if(['record-return-proof','handover','return'].includes(action))body+=field('recipient','Nama penerima');if(action==='resolve-exception')body+=choice('exceptionId','Catatan yang diselesaikan',o.exceptions.filter(e=>e.open).map(e=>[e.id,L(e.type)]));if(!body)body='<p class="full">Konfirmasi tindakan untuk '+esc(o.id)+'.</p>';dialog(actionLabels[action],body,async p=>{if(p.arrivedAt)p.arrivedAt+=':00+07:00';if(p.due)p.due+=':00+07:00';if(action==='set-process-policy')p.required=p.required==='yes';if(action==='refund-pay'&&!p.cashAccount)throw Error('Pilih rekening asal pengembalian dana.');if(action==='process')p.proceedWithoutApproval=p.proceedWithoutApproval==='on';await api('action',{...p,id:o.id,action,revision:o.revision,mutationId:crypto.randomUUID()});await openOrder(o.id);msg('Perubahan tersimpan.');});document.querySelectorAll('#modal input[type=number]').forEach(i=>{if(!i.hasAttribute('min'))i.min='0';if(!i.hasAttribute('step'))i.step='1'});}
function linkInt(){dialog('Pastikan pemilik barang',choice('roomId','Kamar terverifikasi',rooms.filter(r=>r.active).map(r=>r.id))+field('name','Nama pemilik')+field('contact','WhatsApp','tel')+proofSelect()+field('reason','Dasar verifikasi'),async p=>{const v=await api('link-int',{...p,id:selected,revision:detail.order.revision});selected=v.order.id;await openOrder(selected);setTimeout(()=>showLink(v.trackingPath,'Konfirmasi pesanan'),30)});}
function uploadMessage(text,error=false){const out=$('#modal [data-upload-status]');if(out){out.textContent=text;out.className=error?'alert error':'';}else {$('#message').className='alert '+(error?'error':'info');$('#message').textContent=text;}}
async function upload(file,capture){if(!file||uploading)return;const orderId=selected;if(!orderId)return;uploading=true;orderLoad++;const controls=[...document.querySelectorAll('#view button,#view input,#modal button,#modal input')],disabled=controls.map(el=>el.disabled);controls.forEach(el=>el.disabled=true);try{const f=new FormData();f.set('orderId',orderId);f.set('capture',capture);f.set('file',file);const saved=await THUpload.send('/api/laundry/proof',f,{headers:{'X-Top-Hills':'1'},onProgress:n=>uploadMessage(THUpload.progress(n))});stopCamera();if(selected===orderId){detail.proofs.push(saved.proof);const box=$('#action-camera-box')||$('#camera-box');if(box)box.innerHTML='';const select=$('#modal select[name=proofId]');if(select){const option=document.createElement('option');option.value=saved.id;option.textContent=(saved.capture==='live'?'Foto langsung':'Unggahan')+' · baru disimpan';select.append(option);select.value=saved.id;}const li=document.createElement('li'),a=document.createElement('a');a.target='_blank';a.href='/api/laundry/proof?id='+encodeURIComponent(saved.id);a.textContent=(saved.capture==='live'?'Foto langsung':'Unggahan')+' · baru disimpan';li.append(a);$('#proof-list')?.append(li);uploadMessage('Bukti tersimpan. Lanjutkan mengisi langkah ini.');}}catch(e){uploadMessage(THCopy.error(e.message),true);}finally{uploading=false;controls.forEach((el,i)=>el.disabled=el.id==='capture'?false:disabled[i]);}}
function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null;}
async function camera(target='#camera-box'){if(uploading||capturing)return;try{stopCamera();const context=selected,box=$(target);const acquired=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1920},height:{ideal:1080}},audio:false});if(selected!==context||!box.isConnected){acquired.getTracks().forEach(t=>t.stop());return;}stream=acquired;box.innerHTML='<video id="live" autoplay playsinline muted></video><button type="button" id="capture" class="primary">Foto & simpan</button><button type="button" id="stop-camera">Batal foto</button>';$('#live').srcObject=stream;$('#stop-camera').onclick=()=>{stopCamera();box.innerHTML=''};$('#capture').onclick=async()=>{if(uploading||capturing)return;const orderId=selected,orderDetail=detail,v=$('#live'),c=document.createElement('canvas');if(!v.videoWidth)return;capturing=true;const controls=[...document.querySelectorAll('#view button,#view input,#modal button,#modal input')],disabled=controls.map(el=>el.disabled);controls.forEach(el=>el.disabled=true);try{uploadMessage('Menyiapkan foto…');const size=THUpload.dimensions(v.videoWidth,v.videoHeight);c.width=size.width;c.height=size.height;c.getContext('2d').drawImage(v,0,0,c.width,c.height);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/jpeg',.88));if(!blob)throw Error('Foto belum berhasil diambil. Coba lagi.');if(selected!==orderId||detail!==orderDetail)return;await upload(new File([blob],'capture.jpg',{type:'image/jpeg'}),'live');}catch(e){uploadMessage(THCopy.error(e.message),true)}finally{capturing=false;controls.forEach((el,i)=>el.disabled=disabled[i]);}};}catch(e){msg('Kamera belum diizinkan. Izinkan akses kamera di pengaturan browser, lalu coba lagi.',true)}}

$('#modal').addEventListener('close',stopCamera);load();

setInterval(()=>{if(!uploading&&!capturing&&!document.hidden&&!$('#modal').open&&!stream&&!busy&&!document.activeElement?.matches('input,textarea,select')&&tab==='orders'){if(selected)openOrder(selected,true);else load(false);}},15000);

async function closing(){try{tab='closing';const v=await api('summary'),s=v.summary;$('#view').innerHTML=`<button id="back-closing">← Antrean</button><h1 style="margin-top:24px">Pemeriksaan akhir dan pergantian petugas</h1><p class="muted">Bandingkan seluruh paket dan cash yang masih dalam penguasaan Top Hills. Rekap tidak hanya mencakup halaman antrean yang sedang dibuka.</p><div class="metrics"><div class="metric"><small>Paket menurut sistem</small><b>${s.physicalBags||0}</b>kantong yang masih disimpan</div><div class="metric"><small>Uang tunai belum dicocokkan</small><b style="font-size:21px">${rp(s.cashInTransit)}</b>uang penerimaan</div><div class="metric"><small>Pemilik belum diketahui</small><b>${s.openInt||0}</b>perlu identifikasi</div><div class="metric"><small>Dibantu petugas / seluruh pesanan</small><b>${s.assisted||0} / ${s.total||0}</b>${s.accepted||0} sudah diterima</div></div><form class="card grid" id="shift-form">${field('physicalBags','Hasil hitung kantong fisik','number',0)}${field('cash','Hasil hitung tunai (rupiah)','number',0)}<label class="full">Catatan serah terima & tindakan berikutnya<textarea name="note" required minlength="5"></textarea></label><label class="full">Bukti hitung/serah terima<input name="proof" type="file" accept="image/jpeg,image/png,application/pdf" required></label><button class="primary">Ajukan pemeriksaan</button></form><div class="card"><h2>Riwayat pemeriksaan</h2>${v.shifts.map(x=>{const d=JSON.parse(x.data);return `<div class="card"><strong>${esc(THCopy.label(x.action))} · ${esc(THCopy.person(d.actorName||x.actor))}</strong><p>${new Date(x.at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})} · ${esc(THCopy.label(d.status))}</p>${d.bagDifference!==undefined?`<p>Selisih paket ${d.bagDifference} · Selisih tunai ${rp(d.cashDifference)}</p>`:''}<p>${esc(d.note)}</p>${member.role==='Owner'&&x.action==='SHIFT SUBMITTED'&&!v.shifts.some(r=>r.action==='SHIFT REVIEWED'&&JSON.parse(r.data).sourceId===x.id)?`<button data-review-shift="${esc(x.id)}">Periksa laporan</button>`:''}</div>`}).join('')||'<p>Belum ada pergantian petugas yang dicatat.</p>'}</div>`;$('#back-closing').onclick=()=>{tab='orders';load()};$('#shift-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const f=new FormData(e.target),proof=new FormData();proof.set('orderId','SHIFT-'+crypto.randomUUID());proof.set('file',f.get('proof'));const uploaded=await THUpload.send('/api/laundry/proof',proof,{headers:{'X-Top-Hills':'1'},onProgress:n=>{btn.textContent=THUpload.progress(n)}});await api('shift',{physicalBags:f.get('physicalBags'),cash:f.get('cash'),note:f.get('note'),proofId:uploaded.id,mutationId:crypto.randomUUID()});await closing();msg('Pergantian petugas tersimpan untuk diperiksa. Selisih tetap terlihat.');}catch(e){msg(e.message,true)}finally{btn.disabled=false}};document.querySelectorAll('[data-review-shift]').forEach(b=>b.onclick=()=>dialog('Periksa pergantian petugas',field('note','Hasil pemeriksaan'),async p=>{await api('shift-review',{id:b.dataset.reviewShift,...p});await closing()}));}catch(e){msg(e.message,true)}}

window.addEventListener('online',()=>{msg('Koneksi kembali. Mengambil data terbaru.');if(!$('#modal').open&&!uploading)load();});window.addEventListener('offline',()=>msg('Anda offline. Tunggu koneksi sebelum menyimpan.',true));

function revisionPanel(o){
 const labels={name:'Nama',contact:'WhatsApp',relationship:'Hubungan',method:'Penyerahan',serviceIds:'Paket laundry',note:'Instruksi'};
 const pretty=(key,c)=>key==='method'?({pickup:'Jemput kamar',dropoff:'Antar counter'}[c?.method]||c?.method):key==='serviceIds'?UI.ids(c).map(id=>THServices.catalog().find(s=>s.id===id)?.name||id).join(' + '):c?.[key];
 return `<details class="card" ${o.customerRevision>o.acceptedRevision?'open':''}><summary>Perubahan pesanan · versi ${o.customerRevision}</summary><div class="table-wrap"><table><thead><tr><th>Informasi</th><th>Pesanan awal</th><th>Pesanan terbaru (versi ${o.customerRevision})</th></tr></thead><tbody>${Object.entries(labels).map(([key,label])=>{const a=pretty(key,o.initialSnapshot),b=pretty(key,o.customer);return `<tr><td>${label}</td><td>${esc(a||'—')}</td><td>${esc(b||'—')}${a!==b?' <span class="status-badge warning">Berubah</span>':''}</td></tr>`}).join('')}</tbody></table></div><p class="muted">${o.revisionHistory?.length||0} revisi sebelumnya tersimpan. Versi yang sudah dibaca petugas: ${o.acceptedRevision}.</p></details>`;
}
function priceHistory(o){return o.priceHistory?.length?`<details><summary>Riwayat koreksi timbang (${o.priceHistory.length})</summary>${[...o.priceHistory].reverse().map(h=>`<div class="history-entry"><p><strong>${esc(h.name)}</strong> · ${new Date(h.at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}</p><p>${esc(h.reason)}</p>${UI.priceTable(h.price)}</div>`).join('')}</details>`:'';}
function actionPanel(o){
 const f=THLaundryFocus.focus(o,member.role,available(o)),issues=THLaundryFocus.openIssues(o),other=optionalActions(o,f.action);
 const label=f.action==='record-return-proof'?'Lengkapi bukti pengembalian':actionLabels[f.action];
 const issueText=e=>['LABEL MISSING','RELABEL REQUIRED'].includes(e.type)&&o.status==='CANCELLED'?'Catatan label belum ditutup':L(e.type);
 const showIssues=issues.length&&(['resolve-exception','record-return-proof'].includes(f.action)||THLaundryFocus.terminal(o)&&!f.complete);
 return `<div class="row spread"><span class="eyebrow">${f.complete?'SELESAI':f.waitingFor?'MENUNGGU '+esc(f.waitingFor.toUpperCase()):'KERJAKAN SEKARANG'}</span><span class="status-badge ${f.tone}">${f.complete?'Tersimpan':f.action||f.link?'Wajib diselesaikan':'Menunggu tindak lanjut'}</span></div><h2 id="work-now-title">${esc(f.title)}</h2><p>${esc(f.text)}</p>${f.action==='accept'&&o.customerRevision>1?revisionPanel(o):''}${showIssues?`<ul class="focus-issues">${issues.map(e=>'<li>'+esc(issueText(e))+'</li>').join('')}</ul>`:''}${f.action||f.link?`<div class="actions main-action">${f.link?'<a class="button primary" href="/laundry-desk?order='+encodeURIComponent(f.link)+'">Buka pesanan lanjutan</a>':f.action==='link-int'?'<button class="primary" data-guide-link>Pastikan pemilik & buat pesanan</button>':'<button class="primary" data-action="'+f.action+'">'+esc(label)+'</button>'}</div>`:''}${f.action==='approve-price'&&available(o).includes('process')?'<button class="text-action" data-action="process">Pelanggan belum merespons? Lanjutkan dengan alasan</button>':''}${o.status==='IN PROCESS'&&!o.priceApproved?'<p class="waiting-note">Persetujuan harga pelanggan masih perlu dilengkapi sebelum penyerahan.</p>':''}${other.length?'<button class="text-action" id="other-actions">Tindakan lain bila diperlukan</button>':''}`;
}

function reviewScenario(scenarioId=''){
 const o=detail.order;
 const options=THLaundryScenarios.map(s=>[s.id,s.id+' · '+s.title]);
 dialog('Catat pemeriksaan '+member.role,choice('scenarioId','Skenario yang diperiksa',options,scenarioId)+`<p class="alert info full">Pemeriksaan ini dicatat atas nama ${esc(member.name)} (${esc(member.role)}). Status barang, pembayaran dan setoran tetap mengikuti tindakan serta buktinya.</p><label class="full">Hasil pemeriksaan & tindak lanjut<textarea name="note" minlength="10" maxlength="1000" required placeholder="Apa yang sudah diperiksa, apa hasilnya, dan apakah masih perlu ditindaklanjuti?"></textarea></label>`+choice('proofId','Bukti pendukung (opsional)',[['','Tanpa lampiran tambahan'],...detail.proofs.map(p=>[p.id,(p.capture==='live'?'Foto':'Unggahan')+' · '+new Date(p.created_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})])]),async p=>{await api('action',{...p,action:'review-sop',id:o.id,revision:o.revision,mutationId:crypto.randomUUID()});await openOrder(o.id);msg('Pemeriksaan '+member.role+' tersimpan dengan nama dan waktu.');});
}
